String html = R"(<!doctype html><html lang=en><head><meta charset=UTF-8><meta name=viewport content="width=device-width,initial-scale=1"><title>IRB</title><style>*{outline:0;font-family:monospace}body{background-color:#121212;color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh;margin:0;padding:0 20px}h1{font-size:36px;margin-bottom:20px}button{background-color:#6200ea;color:#fff;border:none;border-radius:5px;padding:10px 20px;font-size:16px;cursor:pointer;transition:background-color .3s;margin:5px}button.stop{background-color:#d32f2f}.irCodes{margin-top:20px;padding:20px;border:1px solid #fff;border-radius:5px;width:80%;max-width:320px;height:400px;text-align:center;max-height:300px;overflow-x:hidden;overflow-y:auto;display:flex;flex-direction:column;align-items:center;position:relative}.irCode:first-of-type{margin-top:50px}.irCode{margin:5px;padding:5px;background-color:#333;border-radius:5px;display:flex;justify-content:space-between;align-items:center;width:100%}.selected{background:#4210da}.irCode input{background:0 0;border:none;color:#fff;font-size:14px;width:45%;margin:3px!important}.irCode button{background-color:#6200ea;border-radius:5px;padding:10px 20px;cursor:pointer}#blastButton{border-radius:30px}#downloadButton{position:absolute;top:10px;right:10px}#loadButton{position:absolute;top:10px;left:10px}.delBtn{background-color:#d32f2f!important;border-radius:35px!important;padding:10px!important;margin:3px!important}.note{position:absolute;top:30%}</style></head><body><h1>IRB</h1><button id=blastButton>Blast</button><div class=irCodes id=irCodesDiv><button id=loadButton>Load</button><button id=downloadButton>Save</button></div><script>const blastButton=document.getElementById("blastButton"),irCodesDiv=document.getElementById("irCodesDiv"),downloadButton=document.getElementById("downloadButton"),loadButton=document.getElementById("loadButton");let irCodes=[];function sendBlastRequest(){fetch("/blast",{method:"GET"}).then((e=>e.text())).then((e=>{console.log("Blast response:",e)})).catch((e=>alert(`Error blasting: ${e}`)))}function displayIRCodes(){if(irCodesDiv.innerHTML="",irCodesDiv.appendChild(downloadButton),irCodesDiv.appendChild(loadButton),irCodes.length<1){let e=document.createElement("p");e.innerHTML="IR Codes will be displayed here.<br>Load codes or read new ones!",e.classList.add("note"),irCodesDiv.appendChild(e)}downloadButton.addEventListener("click",download),loadButton.addEventListener("click",load),irCodes.forEach(((e,t)=>{const o=document.createElement("div");o.classList.add("irCode");const d=document.createElement("input");d.value=e.name,d.addEventListener("input",(()=>{e.name=d.value}));const n=document.createElement("button");n.classList.add("delBtn"),n.addEventListener("click",(()=>{irCodes.splice(t,1),displayIRCodes()})),o.addEventListener("click",(t=>{t.target!==d&&t.target!==n&&(document.querySelectorAll(".selected").forEach((e=>e.classList.remove("selected"))),o.classList.add("selected"),sendLoadRequest(e.code))})),o.appendChild(d),o.appendChild(n),irCodesDiv.appendChild(o)}))}function sendLoadRequest(e){fetch(`/loadCode?code=${encodeURIComponent(JSON.stringify(e))}`,{method:"GET"}).then((e=>e.text())).then((e=>{console.log("Load response:",e)})).catch((e=>alert(`Error loading IR code: ${e}`)))}function addIRCode(e){Object.keys(e).length<1||(irCodes.push({name:"New code",code:e}),displayIRCodes())}function download(){const e=JSON.stringify(irCodes),t=new Blob([e],{type:"application/json"}),o=URL.createObjectURL(t),d=document.createElement("a");d.href=o,d.download="ir_codes.json",d.click()}function load(){const e=document.createElement("input");e.type="file",e.accept=".json",e.addEventListener("change",(e=>{const t=e.target.files[0];if(t){const e=new FileReader;e.onload=e=>{try{const t=JSON.parse(e.target.result);irCodes=[...irCodes,...t],displayIRCodes()}catch(e){alert("Failed to load IR codes. Invalid file format.")}},e.readAsText(t)}})),e.click()}blastButton.addEventListener("click",(()=>{"Blast"===blastButton.textContent?(blastButton.textContent="Stop",blastButton.classList.add("stop")):(blastButton.textContent="Blast",blastButton.classList.remove("stop")),sendBlastRequest()})),setInterval((()=>{fetch("/update",{method:"GET"}).then((e=>e.json())).then((e=>{e?(console.log("Update received:",e),addIRCode(e)):console.log("Received empty response from /update")})).catch((e=>alert(`Error during update: ${e}`)))}),1e3),displayIRCodes()</script></body></html>)";
